"""Conversation-repair metadata stamped on tracker events for eval reporting.

Eval reports need to surface corrections and digressions without dedicated
audit event types. The engine stamps a small structured payload onto the
existing events that already mark those transitions:

* **Correction** — nested under :data:`CORRECTION_METADATA_KEY` on the
  :class:`~rasa.shared.core.events.MemorySet` /
  :class:`~rasa.shared.core.events.MemoryCleared` that applied the corrected
  value.
* **Digression** — nested under :data:`DIGRESSION_METADATA_KEY` on the
  :class:`~rasa.shared.core.events.SkillInterrupted` that paused the parent
  skill for a user-initiated skill switch.

Payloads are engine-internal frame / destination ids only (never user text).
Reads are tolerant — missing or malformed records yield ``None``.
"""

from __future__ import annotations

from typing import Any, Dict, Optional

from pydantic import BaseModel, ConfigDict

from rasa.shared.core.events import Event, is_memory_write_event

CORRECTION_METADATA_KEY = "correction"
DIGRESSION_METADATA_KEY = "digression"


class CorrectionMetadata(BaseModel):
    """Trigger-frame context for a successful ``correct()`` apply.

    Attributes:
        flow_id: Flow id of the frame where ``correct()`` succeeded.
        step_id: Step id of that frame.
        skill_id: Skill id of that frame, when known.
    """

    model_config = ConfigDict(frozen=True)

    flow_id: str
    step_id: str
    skill_id: Optional[str] = None

    def as_metadata(self) -> Dict[str, str]:
        """Return the JSON-serializable dict stored under the metadata key."""
        return self.model_dump(exclude_none=True)

    @classmethod
    def from_metadata(cls, data: Any) -> Optional["CorrectionMetadata"]:
        """Rebuild from stored metadata, or ``None`` if not well-formed."""
        if not isinstance(data, dict):
            return None
        flow_id = data.get("flow_id")
        step_id = data.get("step_id")
        if not isinstance(flow_id, str) or not isinstance(step_id, str):
            return None
        skill_id = data.get("skill_id")
        if skill_id is not None and not isinstance(skill_id, str):
            skill_id = None
        return cls(flow_id=flow_id, step_id=step_id, skill_id=skill_id)


class DigressionMetadata(BaseModel):
    """Destination of a digression recorded on ``SkillInterrupted``.

    Source skill / step live on the interrupt event itself; this payload only
    names where the conversation went next.

    Attributes:
        to_flow_id: Flow id activated by the digression.
        to_step_id: First step id of that flow.
        to_skill_id: Skill id of the destination, when known.
    """

    model_config = ConfigDict(frozen=True)

    to_flow_id: str
    to_step_id: str
    to_skill_id: Optional[str] = None

    def as_metadata(self) -> Dict[str, str]:
        """Return the JSON-serializable dict stored under the metadata key."""
        return self.model_dump(exclude_none=True)

    def as_event_metadata(self) -> Dict[str, Any]:
        """Return the full ``Event.metadata`` dict for a digression interrupt."""
        return {DIGRESSION_METADATA_KEY: self.as_metadata()}

    @classmethod
    def from_metadata(cls, data: Any) -> Optional["DigressionMetadata"]:
        """Rebuild from stored metadata, or ``None`` if not well-formed."""
        if not isinstance(data, dict):
            return None
        to_flow_id = data.get("to_flow_id")
        to_step_id = data.get("to_step_id")
        if not isinstance(to_flow_id, str) or not isinstance(to_step_id, str):
            return None
        to_skill_id = data.get("to_skill_id")
        if to_skill_id is not None and not isinstance(to_skill_id, str):
            to_skill_id = None
        return cls(
            to_flow_id=to_flow_id,
            to_step_id=to_step_id,
            to_skill_id=to_skill_id,
        )


def attach_correction_metadata(event: Event, correction: CorrectionMetadata) -> None:
    """Stamp *correction* onto *event*'s metadata in place.

    No-op if the event already carries correction metadata.
    """
    if not is_memory_write_event(event):
        return
    if read_correction_metadata(event) is not None:
        return
    metadata = dict(event.metadata or {})
    metadata[CORRECTION_METADATA_KEY] = correction.as_metadata()
    event.metadata = metadata


def read_correction_metadata(event: Event) -> Optional[CorrectionMetadata]:
    """Return correction metadata stamped on *event*, or ``None``."""
    metadata = getattr(event, "metadata", None)
    if not metadata:
        return None
    return CorrectionMetadata.from_metadata(metadata.get(CORRECTION_METADATA_KEY))


def read_digression_metadata(event: Event) -> Optional[DigressionMetadata]:
    """Return digression metadata stamped on *event*, or ``None``."""
    metadata = getattr(event, "metadata", None)
    if not metadata:
        return None
    return DigressionMetadata.from_metadata(metadata.get(DIGRESSION_METADATA_KEY))
